                    r.write_memory(e, destination_address, 8, value)?;
                    r.move_flags(value, 8);
                    // 0010021c: move.b (a1)+, $1(a7)
                    e.step()?;
                    let value_address = r.address(1)?;
                    let value = u32::from(e.b(value_address)?);
                    r.offset_address(1, 1)?;
                    let destination_address = r.address(7)?.wrapping_add(0x1_u32);
                    r.write_memory(e, destination_address, 8, value)?;
                    r.move_flags(value, 8);
                    // 00100220: move.b (a1)+, $2(a7)
                    e.step()?;
                    let value_address = r.address(1)?;
                    let value = u32::from(e.b(value_address)?);
                    r.offset_address(1, 1)?;
                    let destination_address = r.address(7)?.wrapping_add(0x2_u32);
                    r.write_memory(e, destination_address, 8, value)?;
                    r.move_flags(value, 8);
                    // 00100224: move.b (a1)+, $3(a7)
                    e.step()?;
                    let value_address = r.address(1)?;
                    let value = u32::from(e.b(value_address)?);
                    r.offset_address(1, 1)?;
                    let destination_address = r.address(7)?.wrapping_add(0x3_u32);
                    r.write_memory(e, destination_address, 8, value)?;
                    r.move_flags(value, 8);
                    // 00100228: move.l (a7), d5
                    e.step()?;
                    let value_address = r.address(7)?.wrapping_add(0x0_u32);
                    let value = e.l(value_address)?;
                    r.put_data(5, 32, value);
                    r.move_flags(value, 32);
                    // 0010022a: moveq #$0, d2
                    e.step()?;
                    r.put_data(2, 32, 0x0_u32);
                    r.move_flags(0x0_u32, 32);
                    // 0010022c: bra.b $10027a
